import{_ as o,o as a,c as t,a0 as i}from"./chunks/framework.B6reNh8h.js";const v=JSON.parse('{"title":"Command-Line Help for pavo","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),r={name:"reference/cli.md"};function d(c,e,s,n,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="command-line-help-for-pavo" tabindex="-1">Command-Line Help for <code>pavo</code> <a class="header-anchor" href="#command-line-help-for-pavo" aria-label="Permalink to &quot;Command-Line Help for `pavo`&quot;">​</a></h1><p>This document contains the help content for the <code>pavo</code> command-line program.</p><p>Visualization host for the 9aia tool suite</p><p><strong>Command Overview:</strong></p><ul><li><a href="#pavo"><code>pavo</code>↴</a></li><li><a href="#pavo-drivers"><code>pavo drivers</code>↴</a></li><li><a href="#pavo-views"><code>pavo views</code>↴</a></li><li><a href="#pavo-chrome"><code>pavo chrome</code>↴</a></li><li><a href="#pavo-view"><code>pavo view</code>↴</a></li><li><a href="#pavo-query"><code>pavo query</code>↴</a></li><li><a href="#pavo-submit"><code>pavo submit</code>↴</a></li><li><a href="#pavo-actions"><code>pavo actions</code>↴</a></li><li><a href="#pavo-invoke"><code>pavo invoke</code>↴</a></li><li><a href="#pavo-jobs"><code>pavo jobs</code>↴</a></li><li><a href="#pavo-notifications"><code>pavo notifications</code>↴</a></li><li><a href="#pavo-serve"><code>pavo serve</code>↴</a></li><li><a href="#pavo-open"><code>pavo open</code>↴</a></li><li><a href="#pavo-manifest"><code>pavo manifest</code>↴</a></li><li><a href="#pavo-schema"><code>pavo schema</code>↴</a></li><li><a href="#pavo-gen-cli-docs"><code>pavo gen-cli-docs</code>↴</a></li></ul><h2 id="pavo" tabindex="-1"><code>pavo</code> <a class="header-anchor" href="#pavo" aria-label="Permalink to &quot;`pavo`&quot;">​</a></h2><p>Visualization host for the 9aia tool suite</p><p><strong>Usage:</strong> <code>pavo [COMMAND]</code></p><h6 id="commands" tabindex="-1"><strong>Commands:</strong> <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;**Commands:**&quot;">​</a></h6><ul><li><code>drivers</code> — List discovered pavo-capable drivers</li><li><code>views</code> — List every view as <code>&lt;driver&gt;:&lt;view&gt;</code> refs</li><li><code>chrome</code> — Show merged chrome contributions (navbar/dashboard/statusbar/ routes/sidebar/headerActions/notifications/jobs + extras)</li><li><code>view</code> — Resolve + render a view — <code>pavo view myco:board</code> or a <code>/myco/item?id=T-1</code> route</li><li><code>query</code> — Raw <code>query</code> op passthrough against a driver&#39;s serve</li><li><code>submit</code> — Submit a form&#39;s field values — <code>pavo submit config:edit --param key=myco.theme --param value=dark</code></li><li><code>actions</code> — List the actions a target offers — declared <code>actions[]</code> (manifest, view-node, tree-item scopes) plus ops-manifest derived actions, with danger level + param schemas</li><li><code>invoke</code> — Invoke an action — <code>pavo invoke myco:board refresh</code>. Dispatches the <code>invoke</code> wire op; <code>--json</code> dumps the full ActionResult</li><li><code>jobs</code> — List the aggregated job feed — every <code>contributes.jobs</code> provider driver&#39;s <code>jobs</code> wire op, tagged with its driver</li><li><code>notifications</code> — List the aggregated notification feed — every <code>contributes.notifications</code> provider driver&#39;s <code>notifications</code> wire op, tagged with its driver</li><li><code>serve</code> — Serve the web bridge — localhost HTTP API + static Nuxt host</li><li><code>open</code> — Open a view in the TUI (<code>pavo-tui</code>) — the interactive surface. Falls back to <code>view</code> text output when stdout is not a TTY</li><li><code>manifest</code> — Print the pavo capability manifest (JSON)</li><li><code>schema</code> — Print the CLI verb schema (JSON)</li><li><code>gen-cli-docs</code> — Print the CLI reference as markdown — the docs pipeline (<code>docs:cli</code>) renders <code>docs/reference/cli.md</code> from this</li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li><li><code>-V, --version</code> — Print version</li></ul><h2 id="pavo-drivers" tabindex="-1"><code>pavo drivers</code> <a class="header-anchor" href="#pavo-drivers" aria-label="Permalink to &quot;`pavo drivers`&quot;">​</a></h2><p>List discovered pavo-capable drivers</p><p><strong>Usage:</strong> <code>pavo drivers [OPTIONS]</code></p><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — JSON output</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-views" tabindex="-1"><code>pavo views</code> <a class="header-anchor" href="#pavo-views" aria-label="Permalink to &quot;`pavo views`&quot;">​</a></h2><p>List every view as <code>&lt;driver&gt;:&lt;view&gt;</code> refs</p><p><strong>Usage:</strong> <code>pavo views [OPTIONS]</code></p><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--driver &lt;DRIVER&gt;</code> — Only views of this driver</li><li><code>--json</code> — JSON output</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-chrome" tabindex="-1"><code>pavo chrome</code> <a class="header-anchor" href="#pavo-chrome" aria-label="Permalink to &quot;`pavo chrome`&quot;">​</a></h2><p>Show merged chrome contributions (navbar/dashboard/statusbar/ routes/sidebar/headerActions/notifications/jobs + extras)</p><p><strong>Usage:</strong> <code>pavo chrome [OPTIONS]</code></p><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — JSON output</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-view" tabindex="-1"><code>pavo view</code> <a class="header-anchor" href="#pavo-view" aria-label="Permalink to &quot;`pavo view`&quot;">​</a></h2><p>Resolve + render a view — <code>pavo view myco:board</code> or a <code>/myco/item?id=T-1</code> route</p><p><strong>Usage:</strong> <code>pavo view [OPTIONS] &lt;TARGET&gt;</code></p><h6 id="arguments" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TARGET&gt;</code> — <code>&lt;driver&gt;:&lt;view&gt;</code> deep link (bare <code>&lt;driver&gt;</code> = its first view) or a <code>/route?query</code> matching a declared view route / <code>item_route</code> template</li></ul><h6 id="options-4" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--param &lt;K=V&gt;</code> — View param, <code>key=value</code> (repeatable). Values parse as JSON when possible, else strings. A view&#39;s <code>filter_param</code> (ViewSpec, convention <code>q</code>) is just another <code>--param</code></li><li><code>--format &lt;FORMAT&gt;</code> — Output format — <code>text</code> (default), <code>json</code>, <code>dot</code>, <code>mermaid</code>, or any format a renderer plugin claims (e.g. <code>svg</code>, <code>ascii</code>; see a driver&#39;s manifest <code>renderers</code>) [default: text]</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-query" tabindex="-1"><code>pavo query</code> <a class="header-anchor" href="#pavo-query" aria-label="Permalink to &quot;`pavo query`&quot;">​</a></h2><p>Raw <code>query</code> op passthrough against a driver&#39;s serve</p><p><strong>Usage:</strong> <code>pavo query [OPTIONS] &lt;DRIVER&gt; &lt;QUERY&gt;</code></p><h6 id="arguments-1" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-1" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;DRIVER&gt;</code> — Driver kind</li><li><code>&lt;QUERY&gt;</code> — Query/binding name (or raw product op for thin drivers)</li></ul><h6 id="options-5" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--param &lt;K=V&gt;</code> — Query param, <code>key=value</code> (repeatable)</li><li><code>--json</code> — JSON output</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-submit" tabindex="-1"><code>pavo submit</code> <a class="header-anchor" href="#pavo-submit" aria-label="Permalink to &quot;`pavo submit`&quot;">​</a></h2><p>Submit a form&#39;s field values — <code>pavo submit config:edit --param key=myco.theme --param value=dark</code></p><p><strong>Usage:</strong> <code>pavo submit [OPTIONS] &lt;TARGET&gt;</code></p><h6 id="arguments-2" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-2" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TARGET&gt;</code> — <code>&lt;driver&gt;:&lt;view&gt;</code> deep link the form lives in (bare <code>&lt;driver&gt;</code> = its first view)</li></ul><h6 id="options-6" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-6" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--form &lt;FORM&gt;</code> — Form node id when the view carries several forms (the <code>id</code> of the <code>form</code> ViewNode)</li><li><code>--param &lt;K=V&gt;</code> — Field value, <code>key=value</code> (repeatable) — the form&#39;s field keys. Values parse as JSON when possible, else strings</li><li><code>--json</code> — JSON output — dumps the full SubmitResult</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-actions" tabindex="-1"><code>pavo actions</code> <a class="header-anchor" href="#pavo-actions" aria-label="Permalink to &quot;`pavo actions`&quot;">​</a></h2><p>List the actions a target offers — declared <code>actions[]</code> (manifest, view-node, tree-item scopes) plus ops-manifest derived actions, with danger level + param schemas</p><p><strong>Usage:</strong> <code>pavo actions [OPTIONS] &lt;TARGET&gt;</code></p><h6 id="arguments-3" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-3" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TARGET&gt;</code> — <code>&lt;driver&gt;:&lt;view&gt;</code> deep link, or bare <code>&lt;driver&gt;</code> for manifest-scope actions only</li></ul><h6 id="options-7" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-7" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--param &lt;K=V&gt;</code> — View param, <code>key=value</code> (repeatable) — used when resolving the view to collect node/item actions</li><li><code>--json</code> — JSON output</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-invoke" tabindex="-1"><code>pavo invoke</code> <a class="header-anchor" href="#pavo-invoke" aria-label="Permalink to &quot;`pavo invoke`&quot;">​</a></h2><p>Invoke an action — <code>pavo invoke myco:board refresh</code>. Dispatches the <code>invoke</code> wire op; <code>--json</code> dumps the full ActionResult</p><p><strong>Usage:</strong> <code>pavo invoke [OPTIONS] &lt;TARGET&gt; &lt;ACTION&gt;</code></p><h6 id="arguments-4" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-4" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TARGET&gt;</code> — <code>&lt;driver&gt;:&lt;view&gt;</code> deep link the action lives in (bare <code>&lt;driver&gt;</code> = its first view)</li><li><code>&lt;ACTION&gt;</code> — Action id — see <code>pavo actions &lt;driver&gt;:&lt;view&gt;</code></li></ul><h6 id="options-8" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-8" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--param &lt;K=V&gt;</code> — Action param, <code>key=value</code> (repeatable) — the action&#39;s <code>ParamSchema</code> names. Values parse as JSON when possible, else strings</li><li><code>--target &lt;JSON-OR-STRING&gt;</code> — Opaque action target — JSON (<code>{&quot;id&quot;:&quot;T-1&quot;}</code>) or a bare string. What the action&#39;s <code>target</code> context calls for (selected row, item id, …); the driver interprets it</li><li><code>--target-id &lt;ID&gt;</code> — Shorthand for <code>--target &lt;id&gt;</code> as a plain string — also the <code>type-target</code> confirmation: the id <em>is</em> the typed confirmation, so <code>--yes --target-id T-1</code> is the non-interactive spelling</li><li><code>--yes</code> — Skip confirmation prompts. <code>confirm</code> actions require it off-TTY; <code>type-target</code> actions still need <code>--target-id</code> (the id is the confirmation — <code>--yes</code> only skips the interactive &quot;type it&quot; prompt)</li><li><code>--interactive</code> — Prompt on a TTY for each action param not given via <code>--param</code> (uses the ParamSchema: enum lists options, bool y/n, defaults on empty input). Errors off-TTY</li><li><code>--json</code> — JSON output — dumps the full ActionResult</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-jobs" tabindex="-1"><code>pavo jobs</code> <a class="header-anchor" href="#pavo-jobs" aria-label="Permalink to &quot;`pavo jobs`&quot;">​</a></h2><p>List the aggregated job feed — every <code>contributes.jobs</code> provider driver&#39;s <code>jobs</code> wire op, tagged with its driver</p><p><strong>Usage:</strong> <code>pavo jobs [OPTIONS]</code></p><h6 id="options-9" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-9" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — JSON output</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-notifications" tabindex="-1"><code>pavo notifications</code> <a class="header-anchor" href="#pavo-notifications" aria-label="Permalink to &quot;`pavo notifications`&quot;">​</a></h2><p>List the aggregated notification feed — every <code>contributes.notifications</code> provider driver&#39;s <code>notifications</code> wire op, tagged with its driver</p><p><strong>Usage:</strong> <code>pavo notifications [OPTIONS]</code></p><h6 id="options-10" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-10" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — JSON output</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-serve" tabindex="-1"><code>pavo serve</code> <a class="header-anchor" href="#pavo-serve" aria-label="Permalink to &quot;`pavo serve`&quot;">​</a></h2><p>Serve the web bridge — localhost HTTP API + static Nuxt host</p><p><strong>Usage:</strong> <code>pavo serve [OPTIONS]</code></p><h6 id="options-11" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-11" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--port &lt;PORT&gt;</code> — Port to bind on 127.0.0.1 (0 = pick a free port; the actual port is printed as the first stdout line) [default: 0]</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-open" tabindex="-1"><code>pavo open</code> <a class="header-anchor" href="#pavo-open" aria-label="Permalink to &quot;`pavo open`&quot;">​</a></h2><p>Open a view in the TUI (<code>pavo-tui</code>) — the interactive surface. Falls back to <code>view</code> text output when stdout is not a TTY</p><p><strong>Usage:</strong> <code>pavo open [TARGET]</code></p><h6 id="arguments-5" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-5" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>[TARGET]</code> — <code>&lt;driver&gt;:&lt;view&gt;</code> deep link (bare <code>&lt;driver&gt;</code> = its first view) or a <code>/route?query</code>. Omit to open the TUI dashboard</li></ul><h6 id="options-12" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-12" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-manifest" tabindex="-1"><code>pavo manifest</code> <a class="header-anchor" href="#pavo-manifest" aria-label="Permalink to &quot;`pavo manifest`&quot;">​</a></h2><p>Print the pavo capability manifest (JSON)</p><p><strong>Usage:</strong> <code>pavo manifest</code></p><h6 id="options-13" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-13" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-schema" tabindex="-1"><code>pavo schema</code> <a class="header-anchor" href="#pavo-schema" aria-label="Permalink to &quot;`pavo schema`&quot;">​</a></h2><p>Print the CLI verb schema (JSON)</p><p><strong>Usage:</strong> <code>pavo schema</code></p><h6 id="options-14" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-14" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li></ul><h2 id="pavo-gen-cli-docs" tabindex="-1"><code>pavo gen-cli-docs</code> <a class="header-anchor" href="#pavo-gen-cli-docs" aria-label="Permalink to &quot;`pavo gen-cli-docs`&quot;">​</a></h2><p>Print the CLI reference as markdown — the docs pipeline (<code>docs:cli</code>) renders <code>docs/reference/cli.md</code> from this</p><p><strong>Usage:</strong> <code>pavo gen-cli-docs</code></p><h6 id="options-15" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-15" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-h, --help</code> — Print help</li></ul>',99)])])}const u=o(r,[["render",d]]);export{v as __pageData,u as default};
